(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zm-sj-prepa-chir-j4-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zm-sj-prepa-chir-j4-ide\",\n \"titre\": \"Préparation D.E (J) · J4 Chirurgie IDE\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 57,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Chirurgie · Prépa D.E J4 (IDE) · J4 et J10 identiques\",\n     \"slug\": \"prepa-chir-j4-ide\",\n     \"pages\": \"\",\n     \"count\": 57,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Chirurgie\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant un traumatisme crânien avec signe neurologique ou plaie pénétrante, un scanner est obligatoire d’emblée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours classe dans le groupe 3 le TC avec GCS < 15, signe neurologique, aggravation ou plaie pénétrante. Conduite : scanner d'emblée et surveillance neurologique.\\n\\nSource : NEUROCHIRURGIE L3.pptx, Traumatismes crâniens, III. Conduite à tenir, groupe 3 ; Neurochorurgie.pdf\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un traumatisé crânien qui ouvre les yeux de façon spontanée, répond aux piqûres du membre par le retrait et répond aux questions de façon appropriée a un Glasgow de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"12\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"13\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 13\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ouverture spontanée des yeux = 4 ; retrait du membre à la piqûre = 4 ; réponse appropriée = 5. Total : 4 + 4 + 5 = 13.\\n\\nSource : NEUROCHIRURGIE L3.pptx, score de Glasgow (ouverture des yeux, réponse motrice, réponse verbale)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle de traumatisme crânien grave lorsque le Glasgow est inférieur à 9 après correction des fonctions vitales.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours le dit mot pour mot : « On parle de traumatisme crânien grave lorsque le Glasgow est inférieur à 9 après correction des fonctions vitales » (Glasgow de 3 à 8).\\n\\nSource : Neurochorurgie.pdf, Traumatismes crâniens, niveaux de gravité\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La hernie abdominale étranglée touche exclusivement les personnes de sexe masculin.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La hernie touche aussi la femme. La hernie crurale survient le plus souvent chez la femme de 30 à 60 ans. Son étranglement est plus fréquent que celui de la hernie inguinale.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Hernies, II. Variétés topographiques (hernie crurale)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la hernie discale, le signe de Lasègue consiste à réveiller la douleur empêchant la poursuite du mouvement en soulevant progressivement le membre inférieur avec le genou étendu.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La manœuvre de Lasègue consiste à élever progressivement le membre inférieur, genou étendu. À partir d'un certain angle, la douleur se réveille et déclenche une réaction de défense.\\n\\nSource : Neurochorurgie.pdf, Sciatalgies / hernie discale, II. Signes physiques\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’abcès chaud est une collection purulente aigüe causée par le bacille de Koch.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'abcès chaud est une collection purulente aiguë due à un germe pyogène (staphylocoque, streptocoque…). Le bacille de Koch donne l'abcès froid, collection d'allure chronique.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Abcès chaud (étiologies) et Abcès froid\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’aplatissement du moignon de l’épaule, avec le coup de hache externe au tiers supérieur du bras est le signe de l’épaulette dans les luxations de l’épaule\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la luxation antéro-interne, l'inspection de face montre le signe de l'épaulette, l'aplatissement du moignon de l'épaule et la déformation en coup de hache externe au tiers supérieur du bras. Remarque : Pour le cours, le signe de l'épaulette correspond précisément à la saillie de l'acromion ; l'aplatissement du moignon et le coup de hache l'accompagnent.\\n\\nSource : Traumatologie Complet-2.pdf, Luxation de l'épaule, 3.2.3.1 Inspection\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fracture de Pouteau Colle est une fracture de partie distale du radius ou fracture juxta-articulaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours la définit comme « la fracture de la partie distale du radius ou fracture classique juxta-articulaire ».\\n\\nSource : Traumatologie Complet-2.pdf, Fractures des deux os de l'avant-bras, 3.5.1.1 Fracture de Pouteau-Colles\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la prise en charge des fractures, l’ostéosynthèse se pratique sous anesthésie générale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'ostéosynthèse est la fixation chirurgicale de la fracture par un implant. Dans le cours, la réduction chirurgicale à foyer ouvert et les réductions sous ostéosynthèse se font sous anesthésie générale.\\n\\nSource : Traumatologie Complet-2.pdf, Fractures de l'humérus (5.1.1 réduction sous AG) ; Fractures de la clavicule (6.2 méthode chirurgicale)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La tuméfaction dans la hernie étranglée est dure, irréductible, tendue, expansive et impulsive à la toux.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans l'étranglement, la tuméfaction est dure, tendue, douloureuse, irréductible, mais NON impulsive et NON expansive à la toux. L'impulsion à la toux caractérise la hernie non compliquée.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Hernies, 4.2 Hernie compliquée (étranglement)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__10\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une dénivellation en marche d’escalier avec douleur exquise lorsqu’on palpe le membre est le signe d’une fracture de l’humérus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La dénivellation en marche d'escalier avec douleur exquise à la palpation douce est décrite pour la fracture de la clavicule, pas de l'humérus.\\n\\nSource : Traumatologie Complet-2.pdf, Fractures de la clavicule, 3.2.2 Palpation\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__11\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une contusion abdominale par choc indirect se produit par percussion ou écrasement d’un organe contre la paroi abdominale postérieure.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La percussion ou l'écrasement d'un organe correspond au choc DIRECT. Le choc indirect est dû à la décélération brutale (collision, chute d'un lieu élevé) et entraîne étirement, rupture ou arrachement.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Contusions abdominales, 1.1 Mécanismes\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__12\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’épreuve ultime au lit du malade est le dernier verrou de sécurité à respecter avant toute transfusion sanguine.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le contrôle ultime au lit du malade (test de compatibilité) se fait juste avant de brancher la poche. C'est le dernier contrôle de sécurité de la transfusion. (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__13\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe de Psoas est la palpation douce du flanc gauche qui entraine une douleur controlatérale au cours des appendicites aigües.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le signe du psoas est la douleur à la flexion forcée de la cuisse. La palpation du flanc gauche provoquant une douleur à droite correspond au signe de Rovsing.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Appendicite aiguë, douleur provoquée (signe du psoas)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__14\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Sur les lieux d’un accident, l’infirmier peut tenter de réduire une fracture ouverte.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant une fracture ouverte : pas de manœuvres intempestives et « surtout ne pas chercher à réduire une fracture ouverte ». On nettoie, on fait un pansement stérile et on immobilise.\\n\\nSource : Traumatologie Complet-2.pdf, 8.1.2 Fractures ouvertes (rôle de l'IDE sur les lieux)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__15\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les traumatismes du bassin, lors d’un choc antéro-postérieur, un ou les deux hémi-bassin s’ouvrent en rotation externe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lors d'un choc antéro-postérieur (impact antérieur), un ou les deux hémi-bassins s'ouvrent en rotation externe. Le choc latéral donne au contraire une rotation interne.\\n\\nSource : Traumatologie Complet-2.pdf, Traumatismes du bassin, 1.2.1.2 Compressions antéro-postérieures\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__16\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fracture ouverte est une fracture qui communique avec l’extérieur par une plaie même minime.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La fracture ouverte est une fracture dont le foyer communique avec l'extérieur par une plaie même minime des parties molles.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Généralités sur les fractures, 5.2 Fracture ouverte\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__17\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La primo-infection tuberculeuse se fait par voie aérienne et peut se disséminer par voie sanguine vers d’autres organes parmi lesquels le rachis.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La primo-infection tuberculeuse se fait par voie aérienne au niveau du poumon. Elle peut se disséminer par voie sanguine vers d'autres organes, dont le rachis (mal de Pott).\\n\\nSource : Neurochorurgie.pdf, Mal de Pott, 1.3 Physiopathologie\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__18\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la majorité des cas de sciatalgie ou hernie discale, il s’agit d’un conflit disco-radiculaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La sciatalgie est un symptôme : « Dans la majorité des cas, il s'agit d'un conflit disco-radiculaire ». La hernie discale en est la cause dans 90 % des cas.\\n\\nSource : Neurochorurgie.pdf, Sciatalgies / hernie discale, introduction et étiologies II. QCM (Questions à choix multiple)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__19\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Reliez chaque processus de survenue des occlusions intestinales à son mécanisme (3 bonnes réponses).\\n| Processus | Mécanisme |\\n|---|---|\\n| 1- Occlusion organique | a- Obstruction |\\n| 2- Occlusion dynamique | b- Strangulation |\\n| 3- Occlusion mixte | c- Paralysie des muscles intestinaux |\\n| | d- Appendicite aigüe |\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1, c) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2, a) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1, b) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(3, b) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(3, d) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(2, c)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. (1, b) ; ; E. (3, d) ; ; F. (2, c)\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"L’occlusion organique (mécanique) se fait par obstruction ou strangulation (1-b). L’occlusion dynamique (fonctionnelle) est due au dérèglement nerveux avec paralysie (2-c). L’occlusion mixte (inflammatoire) survient au cours des affections septiques de voisinage, dont l’appendicite (3-d).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions – étiologies 1.1 à 1.3 (p. 121-122)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__20\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Reliez chaque mécanisme de survenue des occlusions intestinales à l’agent d’étranglement.\\n| Mécanisme | Agent d’étranglement |\\n|---|---|\\n| 1- Obstruction | a- Fécalome |\\n| 2- Strangulation | b- Invagination |\\n| 3- Paralysie des muscles intestinaux | c- Volvulus |\\n| | d- Tumeur |\\n| | e- Hypokaliémie |\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1, d) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2, c) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1, b) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(3, e) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(3, d) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(2, a)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. (1, d) ; ; B. (2, c) ; ; D. (3, e) ;\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Obstruction : tumeur de la paroi, corps étranger, fécalome (1-d). Strangulation : volvulus, invagination (2-c). Occlusion fonctionnelle par paralysie : troubles métaboliques comme l’hypokaliémie (3-e). L’invagination n’est pas une obstruction (C faux), le fécalome n’est pas une strangulation (F faux).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions – étiologies (p. 121-122)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__21\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans cette liste, les complications immédiates d’une fracture sont : (3bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Lésions vasculaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cals vicieux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pseudarthrose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Choc hypovolémique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Lésions nerveuses\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Ankylose.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Lésions vasculaires ; D. Choc hypovolémique ; E. Lésions nerveuses\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Complications immédiates : état de choc (traumatique/hémorragique), lésions cutanées, des parties molles, vasculaires et nerveuses. Cal vicieux, pseudarthrose et ankylose sont des complications secondaires ou tardives.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Généralités sur les fractures – VIII. Complications\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__22\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le diagnostic positif de l’appendicite aigüe se fonde sur trois (3) de ces éléments, lesquels ? :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Céphalées\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Douleurs fosse iliaque droite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hématurie terminale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Recherche des douleurs provoquées\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pollakiurie\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Hyperleucocytose à la NFS\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Douleurs fosse iliaque droite ; D. Recherche des douleurs provoquées ; F. Hyperleucocytose à la NFS\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Le diagnostic positif repose sur la douleur de la fosse iliaque droite, la douleur provoquée et la défense ; la NFS montre une hyperleucocytose. Céphalées, hématurie et pollakiurie n'en font pas partie.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Appendicite aiguë, VIII. Diagnostic positif et 5.2.3 Biologie ; Cours de chirurgie traumatique et digestif.pptx\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__23\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Associez chaque type de fracture du fémur à son trait. (3 bonnes réponses) Type de fracture Trait de fracture Fracture du col du fémur Trait oblique, bas en dedans Fracture du trochanter Trait transversal, horizontal et vertical Trait transversal, oblique avec un 3ème fragment Fracture de la diaphyse fémorale osseux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1, c) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(1, b) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(3, a) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(2, a) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(2, b) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(3, c)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. (1, b) ; ; D. (2, a) ; ; F. (3, c)\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Les fractures trochantériennes ont classiquement un trait oblique en bas et en dedans (2-a). Les fractures de la diaphyse ont des traits transversaux, obliques ou spiroïdes avec ou sans troisième fragment (3-c), ce que confirme le cours. Il reste pour le col le trait transversal/vertical (1-b). (trait des fractures du col et du trochanter : hors cours du projet) Remarque : Les lettres a, b, c du tableau ne sont pas imprimées dans le sujet ; elles correspondent à l’ordre des lignes.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Fractures de la diaphyse du fémur – II. Étiologie (diapo 65)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__24\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l’examen somatique d’un traumatisé du bassin, quelles sont les associations qui ne sont pas vraies. (2 bonnes réponses) Symptôme Lésion 1.Le malade urine beaucoup et facilement avec des … a. Rupture vésicale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1, b) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2, d) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(4, a) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(2, b) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(3, c) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(3, a).\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. (2, b) ; ; F. (3, a).\",\n       \"answerLetters\": [\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Repères du cours : la rupture de l’urètre donne une rétention d’urine avec globe vésical et impossibilité d’uriner ; la rupture de la vessie donne une absence de globe et une hématurie ; une lésion du rectum donne une rectorragie, une lésion du vagin des métrorragies. Les associations (2,b) et (3,a) sont celles qui contredisent ces repères. Remarque : Le tableau est presque illisible dans la capture (chargement en cours) : seule la première ligne est visible. L’explication ne peut pas être vérifiée ligne par ligne.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Traumatismes du bassin – complications immédiates\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__25\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces signes, quels sont ceux qui font suspecter un syndrome de VOLKMANN. (3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sueurs froides\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Œdème des extrémités\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Cyanose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Tachycardie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Insensibilité du membre atteint\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Pouls rapide, filant et imprenable\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Œdème des extrémités ; C. Cyanose ; E. Insensibilité du membre atteint\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le syndrome de Volkmann associe douleur, œdème, cyanose, troubles sensitifs (insensibilité) et abolition du pouls radial. Sueurs froides, tachycardie et pouls filant évoquent plutôt un état de choc.\\n\\nSource : Traumatologie Complet-2.pdf, Le syndrome de Wolkmann, 5.2 Étude clinique\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__26\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le type de coma selon Glasgow chez un traumatisé du crâne qui n’ouvre pas les yeux, émet des sons incompréhensibles et fait des mouvements en extension à la douleur est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Traumatisme crânien modéré\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Traumatisme crânien dépassé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Traumatisme crânien grave\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Traumatisme crânien bénin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Traumatisme crânien grave\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Yeux : n'ouvre pas = 1. Verbal : sons incompréhensibles = 2. Moteur : extension = 2. Total 5, soit entre 3 et 8 : traumatisme crânien grave.\\n\\nSource : NEUROCHIRURGIE L3.pptx, score de Glasgow et niveaux de gravité\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__27\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les fractures du fémur, le matin de l’intervention, l’intervention infirmière se résument à trois (3) de de ces activités, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faire la préparation psychologique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Administrer l’anesthésique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réaliser le bilan préopératoire complet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Sonder le client sur prescription\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Prévenir le chirurgien en cas de fièvre\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Accompagner le client au bloc avec son dossier pour le rassurer.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. Sonder le client sur prescription ; E. Prévenir le chirurgien en cas de fièvre ; F. Accompagner le client au bloc avec son dossier pour le rassurer.\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Le matin de l'intervention, le cours prévoit : sondage vésical, prémédication, prévenir le chirurgien en cas de fièvre, accompagner le blessé au bloc avec son dossier. Le bilan et la préparation psychologique se font avant ; l'anesthésie revient à l'anesthésiste.\\n\\nSource : Traumatologie Complet-2.pdf, 8.2.2.6 Les actes le matin de l'intervention\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__28\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez le traumatisé du membre supérieur, l’attitude Desault comprend trois (3) de ces signes, lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Épaule abaissée, projetée en avant ; rapprochée de la ligne médiane\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Abduction du bras et rotation externe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Tête inclinée du côté atteint et bras collé au corps\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Aplatissement du moignon de l’épaule\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Avant-bras semi-fléchi, soutenu par la main du côté opposé\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Crépitation osseuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Épaule abaissée, projetée en avant ; rapprochée de la ligne médiane ; C. Tête inclinée du côté atteint et bras collé au corps ; E. Avant-bras semi-fléchi, soutenu par la main du côté opposé\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"L'attitude de Desault (traumatisé du membre supérieur) : épaule abaissée, projetée en avant, rapprochée de la ligne médiane ; tête inclinée du côté atteint ; avant-bras demi-fléchi soutenu par la main opposée.\\n\\nSource : Traumatologie Complet-2.pdf, Fractures de la clavicule, 3.2.1 Inspection\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__29\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquez trois (3) complications immédiates dans les polytraumatismes dans cette liste.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Complications urinaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hémorragies\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Nécrose ischémique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Coxarthrose\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Fractures associées\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Ankylose\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Complications urinaires ; B. Hémorragies ; E. Fractures associées\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Chez le polytraumatisé, les risques immédiats sont l'hémorragie (et le choc), les lésions associées (fractures) et les lésions viscérales, dont l'atteinte urinaire. Nécrose, coxarthrose et ankylose sont des complications tardives.\\n\\nSource : Traumatologie Complet-2.pdf, Polytraumatisé et Traumatismes du bassin (complications urinaires immédiates)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__30\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquez trois (3) gestes à réaliser si vous vous retrouviez sur les lieux d’un accident.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faire la prémédication\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Baliser les lieux en vue de protéger le blessé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Transporter le blessé sur votre engin ou dans votre véhicule\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Mettre en route une perfusion\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Mettre le blessé en position latérale de sureté ou sécurité\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Faire une immobilisation provisoire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Baliser les lieux en vue de protéger le blessé ; E. Mettre le blessé en position latérale de sureté ou sécurité ; F. Faire une immobilisation provisoire\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Sur les lieux : protéger (baliser), installer en PLS sur un plan dur et immobiliser provisoirement les fractures. On ne transporte pas le blessé dans son propre véhicule. La perfusion et la prémédication ne sont pas des gestes de secouriste.\\n\\nSource : Traumatologie Complet-2.pdf, Conduite à tenir auprès d'un traumatisé des voies publiques (gestes salvateurs) ; 8.1 Soins sur les lieux\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__31\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces symptômes, indiquez trois (3) indications du drainage.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dilatation des bronches\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Appendicite aigüe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Méningite purulente\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cancer de la vessie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pleurésies purulentes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Cavités infectées\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Dilatation des bronches ; E. Pleurésies purulentes ; F. Cavités infectées\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Le drainage évacue une collection de pus ou de liquide : pleurésies purulentes, cavités infectées (abcès) et dilatation des bronches (drainage de posture). (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__32\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans cette liste, indiquez trois (3) contre-indications de transfusion sanguine.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hypertension artérielle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Diabète\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Insuffisance rénale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Anémie chronique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Insuffisance cardiaque\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Œdème aigu du poumon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Hypertension artérielle ; E. Insuffisance cardiaque ; F. Œdème aigu du poumon\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Les surcharges circulatoires (HTA, insuffisance cardiaque, œdème aigu du poumon) contre-indiquent la transfusion ou imposent une grande prudence. L'anémie chronique est au contraire une indication. (explication hors cours du projet)\\n\\nSource : Exercices du Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf) (question 45 sur les contre-indications)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__33\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La surveillance d’un appareillage de drainage consiste à trois (3) de ces activités, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vérifier la perméabilité du drain\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vider le contenu du bocal quotidiennement à heure fixe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Surveiller l’abondance de l’écoulement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Surveiller l’abondance et noter la quantité du liquide sur une feuille de température\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Surveiller les paramètres vitaux\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Vérifier la dépression créée par l’aspiration et la régler au besoin.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Vérifier la perméabilité du drain ; C. Surveiller l’abondance de l’écoulement ; F. Vérifier la dépression créée par l’aspiration et la régler au besoin.\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Surveiller un drainage, c'est vérifier la perméabilité du drain, surveiller l'abondance de l'écoulement et contrôler la dépression d'aspiration (le vide des flacons de Redon).\\n\\nSource : Traumatologie Complet-2.pdf, 8.2.4.1.4 Surveiller les Redons ; Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Péritonites (maintenir le vide dans les flacons)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__34\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Trois (3) de ces tâches ci-dessous font référence à la préparation psychologique avant toute intervention chirurgicale. Ce sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Evaluer l’état physique, nutritionnel et biologique du client\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rassurer le client et le mettre en confiance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prévenir et lutter contre l’infection\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Procéder à la prémédication\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Dissiper ses craintes de l’intervention ou même de la mort\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Lui donner tous les détails de l’intervention\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Rassurer le client et le mettre en confiance ; E. Dissiper ses craintes de l’intervention ou même de la mort ; F. Lui donner tous les détails de l’intervention\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"La préparation psychologique vise à gagner la confiance de l'opéré : le rassurer, dissiper ses craintes et l'informer sur l'intervention. Le bilan physique, la lutte contre l'infection et la prémédication relèvent d'autres préparations. Remarque : « Tous les détails de l'intervention » : le cours parle de rassurer et d'informer, sans préciser jusqu'à tous les détails.\\n\\nSource : Techniques de soins infirmiers spécialisés en chirurgie, L3 (TECHNIQUES DE SOINS INFIRMIERS SPECIALISÉS EN CHIRURGIE.pdf), L'intervention chirurgicale, III. Période pré-opératoire ; Traumatologie Complet-2.pdf, 8.2.2.2\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__35\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Deux (2) complications courantes de la péritonite sont sur cette liste, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémorragie intra abdominale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Occlusion abdominale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Septicémie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ulcère gastroduodénal\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pancréatite aigüe\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Salpingite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Occlusion abdominale ; D. Ulcère gastroduodénal\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La péritonite évolue vers l’iléus paralytique : « à la péritonite s’est ajoutée l’occlusion paralytique ». L’infection peut aussi se généraliser (septicémie).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Péritonites – formes cliniques et physiopathologie (p. 131-132)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__36\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Trois (3) tâches en tant qu’infirmier auprès d’un opéré en salle d’hospitalisation après le bloc opératoire sont dans cette liste, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Surveillance des paramètres\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Evaluer l’état physique, nutritionnel et biologique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Administrer le traitement prescrit\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Préparer psychologiquement la cliente\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Surveiller la plaie opératoire et les drains\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Préparer le champ opératoire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Surveillance des paramètres ; C. Administrer le traitement prescrit ; E. Surveiller la plaie opératoire et les drains\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"En salle d'hospitalisation, l'opéré est surveillé : paramètres vitaux, traitement prescrit, plaie opératoire et drains. Bilan, préparation psychologique et champ opératoire se font avant l'intervention.\\n\\nSource : Traumatologie Complet-2.pdf, 6.2.2 Suivi postopératoire\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__37\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les deux (2) buts du traitement de l’occlusion intestinale sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Lutter contre la fièvre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rétablir la continuité du circuit intestinal normal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Lever l’obstacle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Alimenter le client\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Corriger les désordres humoraux\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Assurer une couverture antibiotique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Lever l’obstacle ; E. Corriger les désordres humoraux\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"« Le traitement des occlusions comporte une double action : la correction des déséquilibres humoraux et la suppression de l'obstacle. »\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Occlusions intestinales aiguës, VI. Traitement\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__38\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous auriez à poser trois (3) gestes entant qu’infirmier avant l’entrée d’un client au bloc opératoire. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Demande de bilan sanguin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Procéder à la réanimation médicale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pose de sonde nasogastrique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire le pansement\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pose de sonde urinaire\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Absorption de la cavité abdominale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Demande de bilan sanguin ; C. Pose de sonde nasogastrique ; E. Pose de sonde urinaire\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Avant le bloc : bilan sanguin (groupage, NFS), sonde naso-gastrique (mettre l'estomac au repos, éviter le syndrome de Mendelson) et sonde urinaire.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Contusions abdominales, IX. Conduite à tenir (moyens médicaux) ; Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Occlusions (gestes d'urgence)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__39\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquez deux (2) complications de la hernie étranglée dans cette liste.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Insuffisance rénale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Insuffisance hépatique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Occlusion intestinale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Appendicite aigüe\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Péritonite aigüe\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Occlusion intestinale ; E. Péritonite aigüe\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"L'étranglement entraîne ischémie, sphacèle puis perforation du viscère hernié : occlusion (grêle ou côlon) et péritonite.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Hernies, 4.2 Hernie compliquée ; Cours de chirurgie traumatique et digestif.pptx, Hernies (péritonite herniaire)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__40\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours des contusions abdominales, le choc direct se produit par :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contre coup produisant des lésions à distance des organes intra abdominaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Percussion ou écrasement d’un organe contre les vertèbres\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"En cas d’accélération ou décélération\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Par effet explosif causé par augmentation soudaine de la pression intra abdominale responsable de multiples lésions.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Percussion ou écrasement d’un organe contre les vertèbres\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans le choc direct, les viscères creux s'écrasent entre la saillie du rachis et la ceinture pelvienne. Le cours parle de « percussion » et d'écrasement contre les vertèbres.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Contusions abdominales, III. Mécanisme ; Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), 1.1 Mécanismes\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__41\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes fonctionnels des traumatismes crânio-encéphaliques sont : (Choisissez trois (3) bonnes réponses).\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Perte de connaissance initiale ou coma d’emblée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Plaie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Douleur\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ecchymose\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Amnésie\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Hématome\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Perte de connaissance initiale ou coma d’emblée ; C. Douleur ; E. Amnésie\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Signes fonctionnels du TC : perte de connaissance initiale, douleur, amnésie, coma d'emblée. Plaie, ecchymose et hématome sont des signes physiques (examen du crâne).\\n\\nSource : Neurochorurgie.pdf, Traumatismes crâniens, 2.1 Signes fonctionnels et 2.2 Signes physiques\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__42\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le traumatisme crânien modéré, le score de Glasgow est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"9 à 12\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"13 à 15\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3 à 8\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 9 à 12\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Glasgow 9 à 12 = traumatisme modéré ; 13 à 15 = bénin ; 3 à 8 = grave.\\n\\nSource : NEUROCHIRURGIE L3, diapo 23\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__43\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans cette liste, choisissez deux bonnes affirmations\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La monoplégie est la présence de mouvement d’intensité moindre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La paraplégie est une paralysie des deux membres inférieurs\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La tétraplégie est une paralysie des quatre membres\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La parésie est une présence de mouvement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La paraplégie est une paralysie des deux membres inférieurs ; C. La tétraplégie est une paralysie des quatre membres\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Paraplégie = paralysie des deux membres inférieurs ; tétraplégie = paralysie des quatre membres. La monoplégie est la paralysie d'un seul membre. La parésie est une présence de mouvement d'intensité diminuée.\\n\\nSource : Neurochorurgie.pdf, Fracture du rachis, 2.2 Signes physiques (examen de la motricité)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__44\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Associez chaque type d’hémorragie cérébrale au type d’intervalle libre. (Choisissez 3 bonnes réponses) Type d’hémorragie cérébrale Type d’intervalle libre 1-Hémorragie Epidurale a- Long intervalle libre. 2-Hémorragie sous durale b- Bref intervalle libre 3-Hémorragie intra crânienne c- Absence d’intervalle libre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(3,c) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2,a) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1,a) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(2,b) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(1,b) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(3,b)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. (3,c) ; ; B. (2,a) ; ; E. (1,b) ;\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"L’hématome extradural (épidural) se révèle après un intervalle libre ; l’hématome intradural (sous-dural) se distingue par « la grande durée de l’intervalle libre ». L’hémorragie intracérébrale entraîne des troubles d’emblée, sans intervalle libre.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Traumatismes crâniens – VI. Épanchements sanguins (diapos 112-113)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__45\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Associez chaque type d’hémorragie cérébrale à l’origine du sang. (Choisissez 3 bonnes réponses) Type d’hémorragie cérébrale Origine du sang 1-Hémorragie Epidurale a-sang artériel méningé 2-Hémorragie sous durale b- sang veineux 3-Hémorragie intra crânienne c-pétéchies ou gros hématomes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(3,c) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2,a) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1,a) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(2,b) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(1,b) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(3,b)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. (3,c) ; ; C. (1,a) ; ; D. (2,b) ;\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"L’hématome extradural vient le plus souvent d’une artère méningée (artère méningée moyenne) ; l’hématome sous-dural, des veines entre cerveau et dure-mère ; l’hémorragie intracérébrale réalise des pétéchies ou un gros hématome dans le parenchyme. (explication hors cours du projet)\\n\\nSource : aucune source trouvée dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__46\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Ces signes sont ceux de la meilleure réponse verbale du score de GLASGOW, exceptés deux (2), lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Confuse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Spontanée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Appropriée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Flexion anormale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Incohérente\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Spontanée ; D. Flexion anormale\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Meilleure réponse verbale : appropriée, confuse, incohérente, incompréhensible, aucune. « Spontanée » appartient à l'ouverture des yeux ; « flexion anormale » appartient à la réponse motrice.\\n\\nSource : NEUROCHIRURGIE L3.pptx, score de Glasgow III. ÉTUDE DE CAS\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__47\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"La quantité de solutés indispensable à M. TINTO le premier jour selon Baxter est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4000 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6000 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8000 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"12000 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 8000 ml\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Règle de Baxter J1 : poids × 4 × % SCB = 57 × 4 × 35 = 7 980 ml, soit environ 8 000 ml.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 2, 5.3 Réanimation hydroélectrolytique (règle de Baxter)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__48\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"La quantité de solutés pour la réanimation de M. TINTO le deuxième jour selon Baxter est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4000 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6000 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8000 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"12000 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 4000 ml\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Baxter J2 = la moitié de J1 : 8 000 / 2 = 4 000 ml. Contrôle : 8 000 + 4 000 = 12 000 ml, la quantité donnée dans le cas.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 2, 5.3 (J2 = ½ QJ1)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__49\",\n       \"num\": \"51\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Le poids de M. TINTO est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"28 Kg\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"57 Kg\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"85 Kg\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"42 Kg\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 57 Kg\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"12 000 ml sur deux jours = 1,5 × (poids × 4 × 35), soit poids × 210. Poids = 12 000 / 210 ≈ 57 kg (l'âge du patient est aussi 57 ans).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 2, 5.3 (règle de Baxter)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__50\",\n       \"num\": \"52\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Au cours de la première journée, les quantités de macromolécules, de glucosé et de bicarbonate à 14p.1000 sont : (Choisissez 3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"3000 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2000 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"6000 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"8000 ml\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"4000 ml\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"1000 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. 3000 ml ; E. 4000 ml ; F. 1000 ml\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Les 8 000 ml du J1 se répartissent en 3 000 ml de macromolécules, 4 000 ml de glucosé et 1 000 ml de bicarbonate (3 000 + 4 000 + 1 000 = 8 000). Le cours (règle d’Evans) prévoit aussi des grosses molécules, et pour les cristalloïdes ¼ de bicarbonate et ¾ de glucosé. (répartition exacte du J1 : hors cours du projet)\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 1 – réanimation du premier jour (règle d’Evans)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__51\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Le débit du sérum glucosé isotonique 5%(SGI) au deuxième jour selon sachant que toute la quantité doit passer en 8 heures est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"62 gouttes/mn\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"83 gouttes/mn\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"160 gouttes/mn\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"46 gouttes/mn\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 62 gouttes/mn\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Débit (gouttes/min) = volume (ml) × 20 / durée (min). 62 gouttes/min en 8 h (480 min) correspond à environ 1 500 ml de SGI au J2. (calcul hors cours du projet)\\n\\nSource : aucune source trouvée dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__52\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"L’interne décide que le taux d’hémoglobine du client soit ramené à 10 g/dl de sang après la transfusion en 2 heures et demie. La quantité de sang envisagée selon le type de sang disponible à la banque de sang est : (Choisissez 2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"855 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1050 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3000 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1800 ml\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"2800 ml\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"1710 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. 855 ml ; F. 1710 ml\",\n       \"answerLetters\": [\n        \"A\",\n        \"F\"\n       ],\n       \"explanation\": \"Remonter l'Hb de 5 à 10 g/dl (Δ = 5) chez 57 kg. Culot globulaire : 5 × 57 × 3 = 855 ml. Sang total : 5 × 57 × 6 = 1 710 ml. (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__53\",\n       \"num\": \"55\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Les débits de la transfusion selon le sang utilisé seront de : (Choisissez 2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"171 gouttes/mn\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"100 gouttes/mn\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"85 gouttes/mn\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"70 gouttes/mn\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"280 gouttes/mn\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"140 gouttes/mn\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. 171 gouttes/mn ; C. 85 gouttes/mn\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Débit = volume × 15 gouttes / 150 min (2 h 30). Culot : 855 × 15 / 150 ≈ 85 gouttes/min. Sang total : 1 710 × 15 / 150 = 171 gouttes/min. (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__54\",\n       \"num\": \"56\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Le chiffre qui permet d’évaluer le pronostic vital chez M. TINTO selon la loi de Baux est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"72\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"107\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"92\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"84\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 107\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La loi de Baux additionne l’âge et le pourcentage de surface brûlée pour estimer le pronostic vital.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 1 – 5.5 Pronostic\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__55\",\n       \"num\": \"57\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Le pronostic vital selon la loi de Baux de M. TINTO est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Guérison certaine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mort quasi-certaine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"50% de chance de guérir ou de mourir\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Mort quasi-certaine\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon le cours : somme < 50 → guérison très probable ; > 100 → mort quasi certaine ; entre 50 et 100 → une chance sur deux. Avec 107, le pronostic est une mort quasi certaine.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 1 – 5.5 Pronostic\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__56\",\n       \"num\": \"58\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Identifier trois (3) signes cardinaux qui ont permis la découverte de l’hypertrophie prostatique de Monsieur TINTO :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Anorexie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pollakiurie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dysurie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Céphalées\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Rétention d’urine\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Diarrhées\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Pollakiurie ; C. Dysurie ; E. Rétention d’urine\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"L'adénome de la prostate se manifeste par la dysurie (premier symptôme), la pollakiurie et la rétention d'urine (globe vésical).\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Adénome de la prostate, 3.1 Signes fonctionnels ; Rétention urinaire\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
